package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	Role  string `json:"role"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "host=db port=5432 user=appuser password=apppass dbname=myapp sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 200 {
		input = input[:200]
	}
	return input
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	term := sanitizeInput(r.URL.Query().Get("q"))
	category := sanitizeInput(r.URL.Query().Get("cat"))

	if term == "" {
		http.Error(w, "Missing search term", 400)
		return
	}

	// Build query with category filter
	query := fmt.Sprintf(
		"SELECT id, name, email, role FROM users WHERE name ILIKE '%%%s%%'",
		term,
	)

	if category != "" {
		query += fmt.Sprintf(" AND department = '%s'", category)
	}

	query += " ORDER BY name LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var r SearchResult
		if err := rows.Scan(&r.ID, &r.Name, &r.Email, &r.Role); err != nil {
			continue
		}
		results = append(results, r)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

// adminResetHandler - internal endpoint for ops team
func adminResetHandler(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Internal-Token")
	if token != os.Getenv("INTERNAL_TOKEN") {
		http.Error(w, "Forbidden", 403)
		return
	}
	_, err := db.Exec("TRUNCATE TABLE search_cache")
	if err != nil {
		http.Error(w, err.Error(), 500)
		return
	}
	w.Write([]byte("cache cleared"))
}

func main() {
	http.HandleFunc("/api/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	http.HandleFunc("/admin/reset", adminResetHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
